window.AVA_DATA = {"day": {"gregorian": "2026-11-03", "weekday": "الثلاثاء", "label": "الثلاثاء الموافق ٣ نوفمبر ٢٠٢٦ م ، ٢٤ بابه ١٧٤٣ ش"}, "readings": [{"label": "مزمور عشية", "book": "سفر المزامير", "ref": "32:11,33:1", "verses": [[32, 11, "افْرَحُوا بِالرَّبِّ وَابْتَهِجُوا يَا أَيُّهَا الصِّدِّيقُونَ، وَاهْتِفُوا يَا جَمِيعَ الْمُسْتَقِيمِي الْقُلُوبِ."], [33, 1, "اِهْتِفُوا أَيُّهَا الصِّدِّيقُونَ بِالرَّبِّ. بِالْمُسْتَقِيمِينَ يَلِيقُ التَّسْبِيحُ."]]}, {"label": "إنجيل عشية", "book": "انجيل متى", "ref": "25:14-23", "verses": [[25, 14, "«وَكَأَنَّمَا إِنْسَانٌ مُسَافِرٌ دَعَا عَبِيدَهُ وَسَلَّمَهُمْ أَمْوَالَهُ،"], [25, 15, "فَأَعْطَى وَاحِدًا خَمْسَ وَزَنَاتٍ، وَآخَرَ وَزْنَتَيْنِ، وَآخَرَ وَزْنَةً. كُلَّ وَاحِدٍ عَلَى قَدْرِ طَاقَتِهِ. وَسَافَرَ لِلْوَقْتِ."], [25, 16, "فَمَضَى الَّذِي أَخَذَ الْخَمْسَ وَزَنَاتٍ وَتَاجَرَ بِهَا، فَرَبحَ خَمْسَ وَزَنَاتٍ أُخَرَ."], [25, 17, "وَهكَذَا الَّذِي أَخَذَ الْوَزْنَتَيْنِ، رَبِحَ أَيْضًا وَزْنَتَيْنِ أُخْرَيَيْنِ."], [25, 18, "وَأَمَّا الَّذِي أَخَذَ الْوَزْنَةَ فَمَضَى وَحَفَرَ فِي الأَرْضِ وَأَخْفَى فِضَّةَ سَيِّدِهِ."], [25, 19, "وَبَعْدَ زَمَانٍ طَوِيل أَتَى سَيِّدُ أُولئِكَ الْعَبِيدِ وَحَاسَبَهُمْ."], [25, 20, "فَجَاءَ الَّذِي أَخَذَ الْخَمْسَ وَزَنَاتٍ وَقَدَّمَ خَمْسَ وَزَنَاتٍ أُخَرَ قَائِلاً: يَا سَيِّدُ، خَمْسَ وَزَنَاتٍ سَلَّمْتَنِي. هُوَذَا خَمْسُ وَزَنَاتٍ أُخَرُ رَبِحْتُهَا فَوْقَهَا."], [25, 21, "فَقَالَ لَهُ سَيِّدُهُ: نِعِمَّا أَيُّهَا الْعَبْدُ الصَّالِحُ وَالأَمِينُ كُنْتَ أَمِينًا فِي الْقَلِيلِ فَأُقِيمُكَ عَلَى الْكَثِيرِ. اُدْخُلْ إِلَى فَرَحِ سَيِّدِكَ."], [25, 22, "ثُمَّ جَاءَ الَّذِي أَخَذَ الْوَزْنَتَيْنِ وَقَالَ: يَا سَيِّدُ، وَزْنَتَيْنِ سَلَّمْتَنِي. هُوَذَا وَزْنَتَانِ أُخْرَيَانِ رَبِحْتُهُمَا فَوْقَهُمَا."], [25, 23, "قَالَ لَهُ سَيِّدُهُ: نِعِمَّا أَيُّهَا الْعَبْدُ الصَّالِحُ الأَمِينُ كُنْتَ أَمِينًا فِي الْقَلِيلِ فَأُقِيمُكَ عَلَى الْكَثِيرِ. اُدْخُلْ إِلَى فَرَحِ سَيِّدِكَ."]]}, {"label": "مزمور باكر", "book": "سفر المزامير", "ref": "33:1,12", "verses": [[33, 1, "اِهْتِفُوا أَيُّهَا الصِّدِّيقُونَ بِالرَّبِّ. بِالْمُسْتَقِيمِينَ يَلِيقُ التَّسْبِيحُ."], [33, 12, "طُوبَى لِلأُمَّةِ الَّتِي الرَّبُّ إِلهُهَا، الشَّعْبِ الَّذِي اخْتَارَهُ مِيرَاثًا لِنَفْسِهِ."]]}, {"label": "إنجيل باكر", "book": "إنجيل لوقا", "ref": "19:11-19", "verses": [[19, 11, "وَإِذْ كَانُوا يَسْمَعُونَ هذَا عَادَ فَقَالَ مَثَلاً، لأَنَّهُ كَانَ قَرِيبًا مِنْ أُورُشَلِيمَ، وَكَانُوا يَظُنُّونَ أَنَّ مَلَكُوتَ اللهِ عَتِيدٌ أَنْ يَظْهَرَ فِي الْحَالِ."], [19, 12, "فَقَالَ:«إِنْسَانٌ شَرِيفُ الْجِنْسِ ذَهَبَ إِلَى كُورَةٍ بَعِيدَةٍ لِيَأْخُذَ لِنَفْسِهِ مُلْكًا وَيَرْجعَ."], [19, 13, "فَدَعَا عَشَرَةَ عَبِيدٍ لَهُ وَأَعْطَاهُمْ عَشَرَةَ أَمْنَاءٍ، وَقَالَ لَهُمْ: تَاجِرُوا حَتَّى آتِيَ."], [19, 14, "وَأَمَّا أَهْلُ مَدِينَتِهِ فَكَانُوا يُبْغِضُونَهُ، فَأَرْسَلُوا وَرَاءَهُ سَفَارَةً قَائِلِينَ: لاَ نُرِيدُ أَنَّ هذَا يَمْلِكُ عَلَيْنَا."], [19, 15, "وَلَمَّا رَجَعَ بَعْدَمَا أَخَذَ الْمُلْكَ، أَمَرَ أَنْ يُدْعَى إِلَيْهِ أُولئِكَ الْعَبِيدُ الَّذِينَ أَعْطَاهُمُ الْفِضَّةَ، لِيَعْرِفَ بِمَا تَاجَرَ كُلُّ وَاحِدٍ."], [19, 16, "فَجَاءَ الأَوَّلُ قَائِلاً: يَا سَيِّدُ، مَنَاكَ رَبحَ عَشَرَةَ أَمْنَاءٍ."], [19, 17, "فَقَالَ لَهُ: نِعِمَّا أَيُّهَا الْعَبْدُ الصَّالِحُ لأَنَّكَ كُنْتَ أَمِينًا فِي الْقَلِيلِ، فَلْيَكُنْ لَكَ سُلْطَانٌ عَلَى عَشْرِ مُدْنٍ."], [19, 18, "ثُمَّ جَاءَ الثَّانِي قَائِلاً: يَا سَيِّدُ، مَنَاكَ عَمِلَ خَمْسَةَ أَمْنَاءٍ."], [19, 19, "فَقَالَ لِهذَا أَيْضًا: وَكُنْ أَنْتَ عَلَى خَمْسِ مُدْنٍ."]]}, {"label": "البولس", "book": "الرسالة إلى فيلبى", "ref": "3:20-4:9", "verses": [[3, 20, "فَإِنَّ سِيرَتَنَا نَحْنُ هِيَ فِي السَّمَاوَاتِ، الَّتِي مِنْهَا أَيْضًا نَنْتَظِرُ مُخَلِّصًا هُوَ الرَّبُّ يَسُوعُ الْمَسِيحُ،"], [3, 21, "الَّذِي سَيُغَيِّرُ شَكْلَ جَسَدِ تَوَاضُعِنَا لِيَكُونَ عَلَى صُورَةِ جَسَدِ مَجْدِهِ، بِحَسَبِ عَمَلِ اسْتِطَاعَتِهِ أَنْ يُخْضِعَ لِنَفْسِهِ كُلَّ شَيْءٍ."], [4, 1, "إِذًا يَا إِخْوَتِي الأَحِبَّاءَ وَالْمُشْتَاقَ إِلَيْهِمْ، يَا سُرُورِي وَإِكْلِيلِي، اثْبُتُوا هكَذَا فِي الرَّبِّ أَيُّهَا الأَحِبَّاءُ."], [4, 2, "أَطْلُبُ إِلَى أَفُودِيَةَ وَأَطْلُبُ إِلَى سِنْتِيخِي أَنْ تَفْتَكِرَا فِكْرًا وَاحِدًا فِي الرَّبِّ."], [4, 3, "نَعَمْ أَسْأَلُكَ أَنْتَ أَيْضًا، يَا شَرِيكِي الْمُخْلِصَ، سَاعِدْ هَاتَيْنِ اللَّتَيْنِ جَاهَدَتَا مَعِي فِي الإِنْجِيلِ، مَعَ أَكْلِيمَنْدُسَ أَيْضًا وَبَاقِي الْعَامِلِينَ مَعِي، الَّذِينَ أَسْمَاؤُهُمْ فِي سِفْرِ الْحَيَاةِ."], [4, 4, "اِفْرَحُوا فِي الرَّبِّ كُلَّ حِينٍ، وَأَقُولُ أَيْضًا: افْرَحُوا."], [4, 5, "لِيَكُنْ حِلْمُكُمْ مَعْرُوفًا عِنْدَ جَمِيعِ النَّاسِ. اَلرَّبُّ قَرِيبٌ."], [4, 6, "لاَ تَهْتَمُّوا بِشَيْءٍ، بَلْ فِي كُلِّ شَيْءٍ بِالصَّلاَةِ وَالدُّعَاءِ مَعَ الشُّكْرِ، لِتُعْلَمْ طِلْبَاتُكُمْ لَدَى اللهِ."], [4, 7, "وَسَلاَمُ اللهِ الَّذِي يَفُوقُ كُلَّ عَقْل، يَحْفَظُ قُلُوبَكُمْ وَأَفْكَارَكُمْ فِي الْمَسِيحِ يَسُوعَ."], [4, 8, "أَخِيرًا أَيُّهَا الإِخْوَةُ كُلُّ مَا هُوَ حَق، كُلُّ مَا هُوَ جَلِيلٌ، كُلُّ مَا هُوَ عَادِلٌ، كُلُّ مَا هُوَ طَاهِرٌ، كُلُّ مَا هُوَ مُسِرٌّ، كُلُّ مَا صِيتُهُ حَسَنٌ، إِنْ كَانَتْ فَضِيلَةٌ وَإِنْ كَانَ مَدْحٌ، فَفِي هذِهِ افْتَكِرُوا."], [4, 9, "وَمَا تَعَلَّمْتُمُوهُ، وَتَسَلَّمْتُمُوهُ، وَسَمِعْتُمُوهُ، وَرَأَيْتُمُوهُ فِيَّ، فَهذَا افْعَلُوا، وَإِلهُ السَّلاَمِ يَكُونُ مَعَكُمْ."]]}, {"label": "الكاثوليكون", "book": "رسالة يعقوب", "ref": "5:9-20", "verses": [[5, 9, "لاَ يَئِنَّ بَعْضُكُمْ عَلَى بَعْضٍ أَيُّهَا الإِخْوَةُ لِئَلاَّ تُدَانُوا. هُوَذَا الدَّيَّانُ وَاقِفٌ قُدَّامَ الْبَابِ."], [5, 10, "خُذُوا يَا إِخْوَتِي مِثَالاً لاحْتِمَالِ الْمَشَقَّاتِ وَالأَنَاةِ: الأَنْبِيَاءَ الَّذِينَ تَكَلَّمُوا بِاسْمِ الرَّبِّ."], [5, 11, "هَا نَحْنُ نُطَوِّبُ الصَّابِرِينَ. قَدْ سَمِعْتُمْ بِصَبْرِ أَيُّوبَ وَرَأَيْتُمْ عَاقِبَةَ الرَّبِّ. لأَنَّ الرَّبَّ كَثِيرُ الرَّحْمَةِ وَرَؤُوفٌ."], [5, 12, "وَلكِنْ قَبْلَ كُلِّ شَيْءٍ يَا إِخْوَتِي، لاَ تَحْلِفُوا، لاَ بِالسَّمَاءِ، وَلاَ بِالأَرْضِ، وَلاَ بِقَسَمٍ آخَرَ. بَلْ لِتَكُنْ نَعَمْكُمْ نَعَمْ، وَلاَكُمْ لاَ، لِئَلاَّ تَقَعُوا تَحْتَ دَيْنُونَةٍ."], [5, 13, "أَعَلَى أَحَدٍ بَيْنَكُمْ مَشَقَّاتٌ؟ فَلْيُصَلِّ. أَمَسْرُورٌ أَحَدٌ؟ فَلْيُرَتِّلْ."], [5, 14, "أَمَرِيضٌ أَحَدٌ بَيْنَكُمْ؟ فَلْيَدْعُ شُيُوخَ الْكَنِيسَةِ فَيُصَلُّوا عَلَيْهِ وَيَدْهَنُوهُ بِزَيْتٍ بِاسْمِ الرَّبِّ،"], [5, 15, "وَصَلاَةُ الإِيمَانِ تَشْفِي الْمَرِيضَ، وَالرَّبُّ يُقِيمُهُ، وَإِنْ كَانَ قَدْ فَعَلَ خَطِيَّةً تُغْفَرُ لَهْ."], [5, 16, "اِعْتَرِفُوا بَعْضُكُمْ لِبَعْضٍ بِالزَّّلاَتِ، وَصَلُّوا بَعْضُكُمْ لأَجْلِ بَعْضٍ، لِكَيْ تُشْفَوْا. طَلِبَةُ الْبَارِّ تَقْتَدِرُ كَثِيرًا فِي فِعْلِهَا."], [5, 17, "كَانَ إِيلِيَّا إِنْسَانًا تَحْتَ الآلاَمِ مِثْلَنَا، وَصَلَّى صَلاَةً أَنْ لاَ تُمْطِرَ، فَلَمْ تُمْطِرْ عَلَى الأَرْضِ ثَلاَثَ سِنِينَ وَسِتَّةَ أَشْهُرٍ."], [5, 18, "ثُمَّ صَلَّى أَيْضًا، فَأَعْطَتِ السَّمَاءُ مَطَرًا، وَأَخْرَجَتِ الأَرْضُ ثَمَرَهَا."], [5, 19, "أَيُّهَا الإِخْوَةُ، إِنْ ضَلَّ أَحَدٌ بَيْنَكُمْ عَنِ الْحَقِّ فَرَدَّهُ أَحَدٌ،"], [5, 20, "فَلْيَعْلَمْ أَنَّ مَنْ رَدَّ خَاطِئًا عَنْ ضَلاَلِ طَرِيقِهِ، يُخَلِّصُ نَفْسًا مِنَ الْمَوْتِ، وَيَسْتُرُ كَثْرَةً مِنَ الْخَطَايَا."]]}, {"label": "الإبركسيس", "book": "سفر أعمال الرسل", "ref": "11:19-26", "verses": [[11, 19, "أَمَّا الَّذِينَ تَشَتَّتُوا مِنْ جَرَّاءِ الضِّيقِ الَّذِي حَصَلَ بِسَبَبِ اسْتِفَانُوسَ فَاجْتَازُوا إِلَى فِينِيقِيَةَ وَقُبْرُسَ وَأَنْطَاكِيَةَ، وَهُمْ لاَ يُكَلِّمُونَ أَحَدًا بِالْكَلِمَةِ إِلاَّ الْيَهُودَ فَقَطْ."], [11, 20, "وَلكِنْ كَانَ مِنْهُمْ قَوْمٌ، وَهُمْ رِجَالٌ قُبْرُسِيُّونَ وَقَيْرَوَانِيُّونَ، الَّذِينَ لَمَّا دَخَلُوا أَنْطَاكِيَةَ كَانُوا يُخَاطِبُونَ الْيُونَانِيِّينَ مُبَشِّرِينَ بِالرَّبِّ يَسُوعَ."], [11, 21, "وَكَانَتْ يَدُ الرَّبِّ مَعَهُمْ، فَآمَنَ عَدَدٌ كَثِيرٌ وَرَجَعُوا إِلَى الرَّبِّ."], [11, 22, "فَسُمِعَ الْخَبَرُ عَنْهُمْ فِي آذَانِ الْكَنِيسَةِ الَّتِي فِي أُورُشَلِيمَ، فَأَرْسَلُوا بَرْنَابَا لِكَيْ يَجْتَازَ إِلَى أَنْطَاكِيَةَ."], [11, 23, "الَّذِي لَمَّا أَتَى وَرَأَى نِعْمَةَ اللهِ فَرِحَ، وَوَعَظَ الْجَمِيعَ أَنْ يَثْبُتُوا فِي الرَّبِّ بِعَزْمِ الْقَلْبِ"], [11, 24, "لأَنَّهُ كَانَ رَجُلاً صَالِحًا وَمُمْتَلِئًا مِنَ الرُّوحِ الْقُدُسِ وَالإِيمَانِ. فَانْضَمَّ إِلَى الرَّبِّ جَمْعٌ غَفِيرٌ."], [11, 25, "ثُمَّ خَرَجَ بَرْنَابَا إِلَى طَرْسُوسَ لِيَطْلُبَ شَاوُلَ. وَلَمَّا وَجَدَهُ جَاءَ بِهِ إِلَى أَنْطَاكِيَةَ."], [11, 26, "فَحَدَثَ أَنَّهُمَا اجْتَمَعَا فِي الْكَنِيسَةِ سَنَةً كَامِلَةً وَعَلَّمَا جَمْعًا غَفِيرًا. وَدُعِيَ التَّلاَمِيذُ «مَسِيحِيِّينَ» فِي أَنْطَاكِيَةَ أَوَّلاً."]]}, {"label": "مزمور القداس", "book": "سفر المزامير", "ref": "34:19,68:4", "verses": [[34, 19, "كَثِيرَةٌ هِيَ بَلاَيَا الصِّدِّيقِ، وَمِنْ جَمِيعِهَا يُنَجِّيهِ الرَّبُّ."], [68, 4, "غَنُّوا ِللهِ. رَنِّمُوا لاسْمِهِ. أَعِدُّوا طَرِيقًا لِلرَّاكِبِ فِي الْقِفَارِ بِاسْمِهِ يَاهْ، وَاهْتِفُوا أَمَامَهُ."]]}, {"label": "إنجيل القداس", "book": "إنجيل لوقا", "ref": "12:32-44", "verses": [[12, 32, "«لاَ تَخَفْ، أَيُّهَا الْقَطِيعُ الصَّغِيرُ، لأَنَّ أَبَاكُمْ قَدْ سُرَّ أَنْ يُعْطِيَكُمُ الْمَلَكُوتَ."], [12, 33, "بِيعُوا مَا لَكُمْ وَأَعْطُوا صَدَقَةً. اِعْمَلُوا لَكُمْ أَكْيَاسًا لاَ تَفْنَى وَكَنْزًا لاَ يَنْفَدُ فِي السَّمَاوَاتِ، حَيْثُ لاَ يَقْرَبُ سَارِقٌ وَلاَ يُبْلِي سُوسٌ،"], [12, 34, "لأَنَّهُ حَيْثُ يَكُونُ كَنْزُكُمْ هُنَاكَ يَكُونُ قَلْبُكُمْ أَيْضًا."], [12, 35, "«لِتَكُنْ أَحْقَاؤُكُمْ مُمَنْطَقَةً وَسُرُجُكُمْ مُوقَدَةً،"], [12, 36, "وَأَنْتُمْ مِثْلُ أُنَاسٍ يَنْتَظِرُونَ سَيِّدَهُمْ مَتَى يَرْجعُ مِنَ الْعُرْسِ، حَتَّى إِذَا جَاءَ وَقَرَعَ يَفْتَحُونَ لَهُ لِلْوَقْتِ."], [12, 37, "طُوبَى لأُولَئِكَ الْعَبِيدِ الَّذِينَ إِذَا جَاءَ سَيِّدُهُمْ يَجِدُهُمْ سَاهِرِينَ. اَلْحَقَّ أَقُولُ لَكُمْ: إِنَّهُ يَتَمَنْطَقُ وَيُتْكِئُهُمْ وَيَتَقَدَّمُ وَيَخْدُمُهُمْ."], [12, 38, "وَإِنْ أَتَى فِي الْهَزِيعِ الثَّانِي أَوْ أَتَى فِي الْهَزِيعِ الثَّالِثِ وَوَجَدَهُمْ هكَذَا، فَطُوبَى لأُولَئِكَ الْعَبِيدِ."], [12, 39, "وَإِنَّمَا اعْلَمُوا هذَا: أَنَّهُ لَوْ عَرَفَ رَبُّ الْبَيْتِ فِي أَيَّةِ سَاعَةٍ يَأْتِي السَّارِقُ لَسَهِرَ، وَلَمْ يَدَعْ بَيْتَهُ يُنْقَبُ."], [12, 40, "فَكُونُوا أَنْتُمْ إِذًا مُسْتَعِدِّينَ، لأَنَّهُ فِي سَاعَةٍ لاَ تَظُنُّونَ يَأْتِي ابْنُ الإِنْسَانِ»."], [12, 41, "فَقَالَ لَهُ بُطْرُسُ:«يَارَبُّ، أَلَنَا تَقُولُ هذَا الْمَثَلَ أَمْ لِلْجَمِيعِ أَيْضًا؟»"], [12, 42, "فَقَالَ الرَّبُّ: «فَمَنْ هُوَ الْوَكِيلُ الأَمِينُ الْحَكِيمُ الَّذِي يُقِيمُهُ سَيِّدُهُ عَلَى خَدَمِهِ لِيُعْطِيَهُمُ الْعُلُوفَةَ فِي حِينِهَا؟"], [12, 43, "طُوبَى لِذلِكَ الْعَبْدِ الَّذِي إِذَا جَاءَ سَيِّدُهُ يَجِدُهُ يَفْعَلُ هكَذَا"], [12, 44, "بِالْحَقِّ أَقُولُ لَكُمْ: إِنَّهُ يُقِيمُهُ عَلَى جَمِيعِ أَمْوَالِهِ."]]}], "synaxarium": {"heading": "اليوم الرابع والعشرون من شهر بابه المبارك", "titles": ["1 – نياحة القديس إيلاريون الكبير الراهب.", "2 – استشهاد القديسين بولس ولُونجينوس ودينة."], "text": ["1 – في مثل هذا اليوم من سنة 87 للشهداء ( 371م ) تنيَّح القديس العظيم الأنبا إيلاريون الكبير. وُلِدَ هذا القديس في بلدة طابا جنوب غزة سنة 292م من أبوين وثنيين، علَّماه الآداب اليونانية، ثم قصد مدينة الإسكندرية لإتمام علومه، وحرَّكته النعمة الإلهية ليدرس العلوم المسيحية، فاقتنع بها واعتنقها ونال سر المعمودية.", "كان إيلاريون محباً للصلاة والعبادة والنسك، فلما سمع عن القديس أنطونيوس الكبير ذهب إليه وتتلمذ على يديه، وبعد مدة من الزمن رجع إيلاريون إلى بلاد فلسطين إذ بلغه انتقال والديه، فوزع أمواله على الفقراء والمساكين، وبنى قلاية وعاش فيها عابداً ناسكاً وكان كثيرون يأتون إليه طالبين صلواته وإرشاده.", "كثر عدد الرهبان حوله، فبنى لهم ديراً وصار لهم أباً ومرشداً ويُعتبر هو بحق مؤسس الرهبنة في فلسطين، وكان كثير من الشعب يأتون إليه يسترشدون به وينالون بركة صلواته. وفي أواخر حياته مضى إلى مدينة قبرص، وعاش هناك في قلاية منفردة حوالي خمس سنوات. وزاره هناك القديس إبيفانيوس، فتنبأ له أنه سيصير أسقفاً على قبرص، وتمت نبوته.", "ولما بلغ هذا الأب القديس ثمانين سنة من عمره قضى معظمها في النسك والعبادة تنيَّح بسلام. ومدحه القديس يوحنا ذهبي الفم، وذكره القديس باسيليوس الكبير في نسكياته.", "بركة صلواته فلتكن معنا آمين.", "2 – وفيه أيضاً تُعيِّد الكنيسة بتذكار استشهاد القديسين بولس ولُونجينوس ودينة.", "بركة صلواتهم فلتكن معنا. ولربنا المجد دائماً أبدياً آمين"]}, "macarius": [{"id": 35, "text": "قال الأب مقاريوس: ضجرتُ وقتاً وأنا في القلايةِ. فخرجتُ إلى البريةِ وعزمتُ على أن أسألَ أيَّ شخصٍ أقابلُه من أجلِ المنفعةِ. وإذا بي أقابلُ صبياً يرعى بقراً. فقلت له: «ماذا أفعلُ أيها الولدُ فإني جائعٌ»؟ فقال لي: «كلْ». فقلتُ: «أكلتُ، ولكني جائعٌ أيضاً». فقال لي: «كلْ دفعةً ثانيةً». فقلت له: «إني أكلتُ دفعاتٍ كثيرةً ولا زلتُ جائعاً». فقال الصبيُ: «لستُ أشكُ في أنك حمارٌ يا راهب، لأنك تحبُّ أن تأكلَ دائماً». فانصرفتُ ولم أردَّ له جواباً."}, {"id": 199, "text": "قال القديس مقاريوس الكبير: «إذا أقدمتَ على الصلاةِ فاحرص أن تكون ثابتاً لئلا تسلِّم إناءَك بيدِ أعدائك. لأنهم يشتهون اختطاف آنيتك التي هي أشواقُ نفسِك، وهي الأشواق الصالحة التي يجب أن تخدم بها الله نهاراً وليلاً. لأن الله لا يطلب أن تمجِّدَه بشفتيك فقط بينما تطيش أفكارُك بأباطيل العالم، لكنه يريد ألا توقف نفسَك أمامه وأفكارك تنظر إليه بدون التفات»."}, {"id": 34, "text": "قيل عن الأنبا مقاريوس إنه بنى لنفسِه قلايةً غربي الملاحات وسكن فيها. وصار يُضَفِّرُ الخوصَ ويعيشُ من عملِ يديه ويعبدُ الله كنحوِ قوتِهِ. فلما سمع به أناسٌ حضروا إليه وسكنوا معه. فكان لهم أباً مرشداً. ولما سمع بسيرةِ الأنبا أنطونيوس وبأعمالهِ الفاضلةِ، مضى إليه فقَبِلَه وعزاه وأرشده إلى طريقِ الرهبنةِ، وألبسه الزيَ ثم عاد إلى موضعِهِ. وكثُرَ الذين يحضرون إليه فكان يُلبسهم الزيَ ويرشدهم إلى طريقِ العبادةِ. فلما كَبُرَ عددُهم بنوا لهم كنيسةً هي الآن موضع البراموس، فلما ضاق بهم المكانُ ولم تعُد الكنيسةُ تسعهم، تحوَّل الأب من ذلك المكانِ وبنى كنيسةً أخرى."}, {"id": 36, "text": "سُئل القديس مقاريوس: «أيُّ الفضائلِ أعظمُ»؟ فأجاب وقال: «إن كان التكبُّر يُعتبرُ أشرَّ الرذائلِ كلِّها حتى أنه طرح طائفةً من الملائكةِ من علوِ السماءِ، فبلا شكٍ يكون التواضعُ أكبرَ الفضائلِ كلِّها، لأنه قادرٌ أن يرفعَ المتمسكَ به من الأعماقِ حتى ولو كان خاطئاً. من أجلِ ذلك أعطى الربُّ الطوبى للمساكين بالروحِ»."}, {"id": 38, "text": "وحدث مرة أن مضى الأنبا مقاريوس إلى القديس أنطونيوس في الجبلِ وقرع بابَه. فقال الأنبا أنطونيوس: «من يقرعُ البابَ»؟ فقال: «أنا مقاريوس أيها الأب». فتركه الأنبا أنطونيوس ودخل ولم يفتح له البابَ. لكنه لما رأى صبرَه فتح له أخيراً وفرح معه وقال له: «منذ زمانٍ وأنا مشتاقٌ أن أراك». وأراحه لأنه كان مجهداً من أثر تعبٍ شديدٍ. فلما حان المساءُ بلَّ أنطونيوس قليلاً من الخوصِ لنفسِهِ. فقال له مقاريوس: «أتسمح أن أبلَّ لنفسي أنا أيضاً قليلاً من الخوصِ»؟ فقال له: «بلّ». فأصلح حُزمةً كبيرةً وبلَّها وجلسا يتكلمان عن خلاصِ النفسِ. وكانت الضفيرةُ تنحدرُ من الطاقةِ. فرأى أنبا أنطونيوس باكراً أن مقاريوس قد ضَفَّرَ كثيراً فقال: «إن قوةً كبيرةً تخرجُ من هاتين اليدين»."}, {"id": 39, "text": "ومرة نزل الأب مقاريوس من الإسقيط إلى الحصادِ وصَحِبَه سبعةُ إخوةٍ. وكانت امرأةٌ تلتقطُ خلفَ الحصَّادين وهي لا تكفُّ عن البكاءِ. فاستفهم الأب من رئيسِ الحصَّادين عن أمرِ هذه العجوز وعن سببِ بكائها دائماً. فأجابه: «إن رجلَها عنده وديعةٌ لإنسانٍ مقتدرٍ. وقد مات فجأةً ولا تعلم المرأةُ موضعَ هذه الوديعةِ. وقد عَزِمَ صاحبُها على أخذِ أولادها عبيداً». فلما استراح الحصَّادون من الحرِّ، دعا الشيخُ المرأةَ وقال لها: «هلمي أريني قبرَ زوجِك». فلما وصل إليه صلى مع الإخوةِ. ثم نادي الميتَ قائلاً: «يا فلان، أين تركتَ الوديعةَ»؟ فأجابه: «إنها في بيتي تحتَ رِجلِ السريرِ». فقال له القديسُ: «نَمْ أيضاً». فلما عاين الإخوةُ ذلك تعجبوا. فقال لهم القديسُ: «ليس من أجلي كان هذا الأمرُ لأني لستُ شيئاً. بل إنما صنع اللهُ هذا من أجلِ الأرملةِ واليتامى». ولما سمعت المرأةُ بموضعِ الوديعةِ، انطلقتْ وأخذتها وأعطتها لصاحبها. وكلُّ الذين سمعوا هذا سبَّحوا الله."}, {"id": 40, "text": "قيل عن الأب مقاريوس: إنه كان قد جعل لنفسِه قانوناً وهو أنه إذا قدَّم له الإخوةُ نبيذاً كان لا يمتنع من شربهِ، لكنه عِوض كلِّ قدحِ نبيذٍ يشربه، كان يصومُ عن شربِ الماءِ يوماً. فأما الإخوة فلكي ما يكرِّموه كانوا يعطونه، وهو لم يمتنع بدورِهِ إمعاناً في تعذيبِ ذاتهِ. أما تلميذُهُ فلمعرفتِه بأمرِ معلمِه، طلب من الإخوةِ من أجلِ الربِّ ألا يعطوا الشيخَ نبيذاً لأنه يعذِّبُ ذاتَه بالعطشِ. فلما علموا الأمرَ امتنعوا من إعطائهِ نبيذاً منذ ذلك الوقتِ."}, {"id": 41, "text": "صعد الأب مقاريوس مرةً من الإسقيط إلى البريةِ. فأتى إلى ناووس (أي هيكل وثني) حيث كانت هناك جثثٌ يونانيةٌ قديمةٌ. فأخذ القديسُ جمجمةً ووضعها تحت رأسِهِ. فلما رأى الشياطينُ جسارتَه حسدوه وأرادوا أن يُزعجوه. فنادوا بصوتٍ عالٍ باسمٍ مستعارٍ لامرأةٍ قائلين: «يا فلانة، قد أخذنا الصابونَ والأشنانَ وأدواتِ الحمامِ، وها نحن في انتظارك لتكوني معنا». فخرج صوتٌ من الجمجمةِِ من تحتِ رأسِهِ قائلاً: «إن عندي ضيفاً وهو رجلٌ غريبٌ متوسدٌ عليَّ فلا يمكنني المجيء، امضوا أنتم». أما القديسُ فإنه لم ينزعج ولكنه رفع رأسَه عنها وحرَّكها بيدهِ قائلاً: «ها أنذا قُمتُ عنكِ، فإن استطعتِ الذهابَ فانطلقي معهم إلى الظلمةِ». ثم عاد ووضع رأسَه عليها. فلما رأي الشياطينُ ذلك منه تركوه بخزيٍ عظيمٍ وصرخوا قائلين: «امضِ عنا يا مقاريوس»، وهربوا."}, {"id": 42, "text": "انطلق الأب مقاريوس مرةً من الإسقيط حاملاً زنابيل فأعيا من شدةِ التعبِ، ووضع الزنابيلَ على الأرضِ وصلَّى قائلاً: «يا ربُّ، أنت تعلمُ أنه ما بقي فيَّ قوةٌ»، وإذ به يجدُ نفسَه على شاطئ النهرِ."}, {"id": 43, "text": "أتى أخٌ إلى الأب مقاريوس وقال له: «يا معلم قل لي كلمةً تنفعُني». فقال له القديسُ: «امضِ إلى المقابرِ واشتم الموتى». فمضى الأخُ وشتمهم ورجمهم وعاد وأخبر الشيخَ بما عَمِله. فقال له الشيخُ: «أما خاطبوك بشيءٍ»؟ فقال: «لا». فقال له الشيخُ: «امضِ غداً وامدحهم». فمضى الأخُ ومدحهم قائلاً: «يا قديسينَ، يا أبرار، يا صديقين». وعاد وأخبر الشيخَ بما صنعه. فقال له: «أما أجابوك بشيءٍ»؟ قال: «لا». قال الشيخُ: «إن كنتَ حقاً قد مُتَّ مع المسيحِ ودُفنتَ معه فاصنع هكذا مثلَ أولئك الأمواتِ، لأن الميتَ لا يحسُ بكرامةٍ ولا بإهانةٍ. وبذلك تستطيعُ أن تخلصَ». فانتفع الأخُ بذلك."}, {"id": 45, "text": "كان الأب مقاريوس يقولُ للإخوةِ: «إذا سُرِّحت الكنيسةُ فرُّوا يا إخوةُ فرُّوا». فقال أحدُ الآباءِ: «أيها الأب، إلى أين نفرُّ أكثرَ من هذه البريةِ»؟ فضرب بيدِهِ على فمِهِ وقال: «من هذا فرُّوا»."}, {"id": 48, "text": "قيل عن القديس مقاريوس إنه كان يوصي تلاميذَه قائلاً: «اهربوا من كلامِ النساءِ المؤدي إلى الهلاكِ». وكان يقول: «احذروا ألا تكون بينكم وبين صبيٍ دالةٌ، لأن الصبيَ إذا رأيتَه صاعداً إلى السماءِ فهو سريعُ السقوطِ. فما عليكم إلا أن تطلبوا من المسيحِ إلهِنا أن يُعينَه»."}, {"id": 50, "text": "قيل عن الأب مقاريوس مرة إنه مضى إلى البهلس ليقطع خوصاً، فأتاه الشيطانُ وأخذ منه المِنجلَ وهمَّ ليضربه به. أما هو فلم يفزع بل قال له: «إن كان السيدُ المسيح قد أعطاك سلطاناً عليَّ فها أنا مستعدٌ لأن تقتلَني»؛ فانهزم الشيطانُ وانصرف عنه هارباً."}, {"id": 52, "text": "وحدث مرةً أن أرسلَ شيوخُ الجبلِ إلى الأنبا مقاريوس يقولون له: «سِرْ إلينا لنشاهدَك قبل أن تنصرفَ إلى الربِّ ولا تضطرَّ الشعبَ إلى المجيءِ إليك». فلما سار إلى الجبلِ اجتمع إليه الشعبُ كلُّه. وطلب إليه الشيوخُ قائلين: «قل للشعبِ كلمةً أيها الأب». فقال: «لنبكِ أيها الإخوةُ ولتَسِل دموعُنا من أعيننا قبل أن نمضي إلى حيث تَحرِقُ دموعُنا أجسادَنا بدونِ نفعٍ». فلما قال هذا بكى وبكى الكلُّ معه، وخروا على وجوهِهم قائلين: «أيها الأب صلِّ من أجلنا»."}, {"id": 53, "text": "سأله الشيوخُ مرة: «كيف نصلي»؟ فقال: «نبسط أيدينا إلى الله ونقول: يا الله أهدنا كما تحبُّ وكما تريدُ. وإن أصابتنا ضيقةٌ قلنا: يا ربُّ أعنا. فهو يعرف ما هو خيرٌ لنا ويصنع معنا كرحمتِه ومحبتهِ للبشرِ»."}, {"id": 200, "text": "وقال أيضاً: «إن طولَ الروح هو صبر، والصبر هو الغلبة، والغلبة هي الحياة، والحياة هي الملكوت، والملكوت هو الله سبحانه وتعالى. البئرُ عميقةٌ ولكن ماءها طيبٌ عذب. الباب ضيقٌ والطريقُ كربةٌ ولكن المدينةَ مملوءةٌ فرحاً وسروراً. البرجُ شامخٌ حصينٌ، ولكن داخله كنوزاً جليلة. الصومُ ثقيلٌ صعب لكنه يوصل إلى ملكوت السماوات. فِعلُ الصلاحِ عسيرٌ شاق، ولكنه ينجي من النار برحمة ربِنا الذي له المجد»."}, {"id": 201, "text": "وقال أيضاً: «ضع همَّك كلَّه في أن تطلب الله وأن تنجو من أيدي أعدائك. فالآن يا رجل الله إن وضعتَ في قلبك أن تقتني الوحدةَ فهيئ ذاتك لها، واصبر على المسكنةِ فإن الوحدةَ والمسكنةَ عظيمتان وليس شيءٌ من المواهب يساويهما في القدرِ والكرامة، لأنهما يقرِّبان إلى الله. كما لا تُحصى المواهب الموجودة داخلهما لأنهما يسودان جميعَ الفضائل. وهما في وسط جميع المواهب يتلألآن لأنهما مصدر أعمال القديسين، وجميعُ القديسين وجدوا الله فيهما وكُشفت لهم الأفكار فوهبهم الله قلوباً نقية وهم في المسكنةِ والوحدةِ جياعاً عطاشى. هؤلاء الذين لم يستحقهم العالم. تائهين في البراري والقفار والمغارات وشقوق الأرض. هؤلاء الذين لهم هذه الشهادة الجليلة، قد وجدوا الله في الوحدةِ وبالمسكنةِ والصبر، لأن مجدَ الوحدةِ غيرُ محدودٍ ورجاءَها وفرحَها هو اللهُ، وهي العزاءُ في الفقرِ والمسكنة. غذاؤها الصبر وخدمتها الكاملة هي الطهارة وفرحها هو الاتضاع. هي التي لا يُفسدها سوسٌ ولا يتدنس لها ثوبٌ لأنها ساكنةٌ في الطهارةِ»."}, {"id": 202, "text": "سأل أخٌ الأب مقاريوس عن الوحدةِ، فأجاب الشيخُ وقال: «إن كنتَ تريد السكنى في الوحدةِ فاصبر لها ولا تؤدي عملك يوماً في الداخل ويوماً في الخارج، ولكن تصبر لها باتضاعٍ والله الصالح يؤازرك. لا توجِد سبباً للخروج عن الوحدةِ حتى ولو ليومٍ واحدٍ. بل اثبت في مسكنك لتذوق حلاوتها. ولا تبطئ خارجاً لئلا تجذبَ إليك المضادَ وتتجدد عليك أتعابُك وتُحرم من الصبر. لا تبطئ خارج قلايتك لئلا تجد أتعابك قدامك عند رجوعك، فتتعب جداً في حربك ويصعُب انتصارُك. يا رجل الله حتى متى تدوم لك هذه الأتعاب. اصبر للمسكنة، وعزاءُ الوحدةِ يأتيك من قِبل الله، لا تضيِّع يوماً واحداً لك ونعمةُ الوحدةِ وحلاوةُ المسكنةِ تصيران لك عزاءً ويعطيك الله سعادةً في مسكنِك»."}, {"id": 203, "text": "وسأله أخٌ مرةً قائلاً: «ماذا أصنعُ يا أبي والأفكارُ توعز إليَّ بأن أمضي وأفتقد المرضى فإن هذه هي الوصية». أجابه الشيخُ قائلاً: «إن كلمة النبوة لا تسقط أبداً، فإنه يقول: جيدٌ للرجل أن يحملَ النيرَ منذ صباه ويجلس وحده صامتاً. أما قول ربنا يسوع المسيح: كنتُ مريضاً فزرتموني، فقد قاله لعامة الناس. وإني أقول لك يا أخي: إن الجلوسَ في القلاية أفضلُ من افتقاد المرضى، لأنه يأتي زمانٌ يُضحك فيه على سكان القلالي فتتم كلمة البار أنطونيوس إذ قال: يجيء زمانٌ يُجنُّ فيه جميعُ الناسِ. وإذا أبصروا واحداً لم يُجنّ يذيعون عنه بأنه مجنونٌ لأنه لا يشبههم. وإني أقول لك يا ولدي: إن موسى النبي العظيم لو لم يبتعد من مخالطةِ الناس ومحادثاتهم ويدخل في الضبابِ وحده، لما تسلَّم لوحي العهد المكتوبين بإصبع الله»."}, {"id": 204, "text": "وقال أيضاً: «كمثلِ إنسانٍ إذا دخل إلى الحمَّامِ إن لم يخلع ثيابَه لا ينعم بالاستحمامِ، كذلك الإنسانُ الذي أقدم إلى الرهبنةِ ولم يتعرَّ أولاً من كلِّ اهتمامِ العالم وجميعِ شهواتهِ وملذَّاتهِ، فلن يستطيعَ أن يصيرَ راهباً ولن يبلغَ حدَّ الفضيلةِ. ولن يمكنه كذلك أن يقفَ قبالة جميع سهامِ العدو التي هي شهوات النفس»."}, {"id": 205, "text": "وقال أيضاً: «كمثلِ الحديد الذي إذا طرحتَه في النار يصيرُ أبيضَ ويتنقَّى من الشوائبِ، كذلك النفس إذا ما حلَّ فيها الروحُ القدس المعزي وسكن فيها فإنها تصير نقيةً كالملح متلألئة ببياض الفضيلة، فتنسى الأرضيات وتشتاق إلى السماويات، وتوجد في كل وقتٍ سكرانةً بالإلهيات شغوفةً بالعلويات. وذلك من أجلِ نقاوتها وطهارتها حتى يظن الإنسانُ أنه قد انتقل من هذا العالمِ إلى الحياةِ الأبدية بربنا يسوع المسيح، ويرى الجزاءَ الكاملَ العادلَ العتيد أن يكون للأبرارِ والخطاةِ في الدهرِ الآتي الذي لن يزولَ الدائم إلى الأبد»."}, {"id": 206, "text": "وقال أيضاً: «كما أن المطرَ إذا سقط على الأرضِ تنبتُ وتُنتج الثمارَ، وفي ذلك راحةٌ وفرحٌ للناس، كذلك الدموع إذا ما وقعت على قلبٍ أثمرت ثماراً روحانية وراحةً للنفسِ والجسدِ معاً»."}, {"id": 207, "text": "وقال أيضاً: «ليس شيءٌ يعلو على خوفِ الله. لأنه يسود على كل شيءٍ. فبخوفِ الله يحيدُ كلُّ إنسانٍ عن كلِّ الشرور. فلنقتنِ لنا هذا، ولنبتعدْ عن كلِّ ما لا يريدهُ الله. ولنصنعْ كلَّ ما يُرضيه ونحفظه. ولا نصنع شيئاً يغضبه. ولنعلم أيضاً أن كلَّ ما نعمله عريانٌ ومكشوفٌ لديه ولا تخفى عليه خافيةٌ»."}, {"id": 208, "text": "وقال أيضاً: «إن النفسَ لها استطاعةٌ أن تنظرَ إلى الله في كلِّ حينٍ، فتوجِد لها دالةً عند سيدها، لأنها حينئذ يكون لها قدرةٌ على ذلك، لذلك فلنحرص بكلِّ قوتنا ألا نحيدَ عن خوفِ الله ولا نتعبد للأوجاعِ»."}, {"id": 209, "text": "وقال أيضاً: «يجبُ على الراهبِ أن يكونَ في سكونٍ في كلِّ حين ولا يسمع لأفكارِه التي توعز إليه بكثرةِ الكلامِ الذي يُضعف النفسَ، بل ليمسك عن الكلام حتى ولو نظر أناساً يضحكون أو يتحدثون بكلامٍ لا منفعة له وذلك لجهلِهم. لأن الراهبَ الحقيقي يجب أن يتحفظ من لسانِه كما هو مكتوبٌ في المزمور: اللهم اجعل لفمي حافظاً وعلى شفتيَّ ستراً حصيناً. فالراهب الذي يسلك هكذا لا يعثر أبداً بلسانِه، ولكنه يصبح إلهاً على الأرضِ»."}, {"id": 210, "text": "وقال أيضاً: «كما أن الماءَ إذا سُلِّط على النارِ يُطفئها ويغسل كلَّ ما أكلته، كذلك أيضاً التوبةُ التي وهبها لنا الربُّ يسوع تغسلُ جميعَ الخطايا والأوجاع والشهوات التي للنفسِ والجسدِ معاً»."}], "matta": ["ان كان موت المسيح على الصليب ..قد صالح الله بالانسان و رفع العداوة الأزلية ..فكيف تبقى بعد خصومة بين انسان و اخيه الانسان !!", "مجرد الاحساس بالوجود في حضرة الله ، كفيل أن يعطى الإنسان سلاما قلبيا يفوق العقل بكل اضطراباته وعجزه .", "يا إخوة ، يا بني النور ،اشعلوا مصابيحكم بالحب ،ليكون لكم نور الحياة .", "كنا نتحرق شوقاً بين أنفسنا أن نعرف ما هي أفكار الله عننا ، كل واحد في وضعه و في حالته : المريض، المتألم، المظلوم، الخاطئ؟ فعرفنها و لمسناها في كلماتك مع السامرية و الكنعانية و الأطفال الصغار، ولمسات يدك و عطفك الفائض علي الأبرص و المشلول و الاصم و الأعمي، كلها أحسسنا بها ففرحنا بالله،..... إن كان الله هو أنت", "الصلاة مهما كانت تذللية ومهما أحس الانسان أثناءها بعدم استحقاقه الحديث مع الله بسبب كثرة تعدياته و ذنوبه و دناءاته ..فهي فوق كل هذا علامة محبة متبادلة مع الله ...فمحبة الله ظهرت في جذب الانسان للصلاة و الوقوف في حضرته و محبة الانسان ظهرت في تقديم القلب لله و لو بصورته الحزينة الآثمة النادمة .", "كل شئ سيذبل ويتلاشى إلا الحب ، فهو الأجنحة الروحية التي ستحملنا في النهاية وتطير لتحط بنا في حضرة المحبوب ...آه يا ابن الله ، تعال ولتحرقنى نار حبك.", "الأمور الجسدية يعطيها المسيح لنا بلا طلب ... أما الأمور الروحية فلا يمكن أن يعطيها الله بلا طلب", "الخطية تستنفذ قوى الانسان الجسدية و النفسية ..و لكنها لا تستنفذ رحمة الله و محبته ..فالله أقوى من الانسان ( 1 كو 1 : 25 ) و لا يزال محباً للانسان قبل أن يخطئ و أثناء ما يخطئ و بعد أن يخطئ.", "كنا نسأل , هل موازين الله كموازين البشر؟ يعني هل الخاطئ المنبوذ عند الناس يكون كذلك حتماً عند الله ؟ فلما قلت للزانية أذهبي بسلام أنا لا أدينك، تأكدنا أنك أنت أنت الله و لست أنساناً مثلنا ، تري ما لا نراه و تحكم بما هو فوق أحكامنا ففرحنا أن لنا عند الله رحمة غير موجودة عند بني جلدتنا.", "كل من لم يجد يسوع بعد ..يظن أنه غير معروف عند يسوع ...ولكن حينما نقبل اليه و نعرفه ..حينئذ نعرف انه كان يرانا ..كان يتبعنا ..كان يرصد تحركنا و يتعقبنا في كل مكان .", "الأعمال الصالحة خطرة\r\nلأنها تجيز للنفس الضعيفة أن تعتقد خطأ أنها منبع العمل الصالح، وبالتالي تكون هي منبع الصلاح, في حين أن العمل شيء والصلاح شيء آخر. فالكنـز الصالح الذي يستقر في القلب فيجعله صالحاً ويهبه قوة العمل الصالح هو الله نفسه؛ هو الروح القدس \"الكنـز الوحيد للصلاح\", «لماذا تدعوني صالحاً, ليس أحدٌ صالحاً إلا واحد وهو الله» (مت 19: 17).\r\nالله هو سبب الصلاح وأصل القداسة وعِلَّتها الأولى والأخيرة وليس الإنسان, مهما كان.", "الدموع من يستطيع ان يفسر هذة اللغة انها المشاعر كلها مذابة فى نقطة هى لسان يتكلم جميع اللغات هى عزاء المظلوم هى وطن الغريب هى ابو اليتيم هى راحة المتعبين هى تكفير الذنوب هى علامة الندامة هى عهد التوبة هى لغة الروح هى صلاة الصامت هى احتقار العالم هى الحنين الى السماء هى انتظار الموت والانتصار علية الانسان لايستطيع ان يوجة نموه الروحى كيفما شاء ولكنة حينما يستسلم لله ينمو اعظم واكثر وافضل مما شاء لا توقف جهادك وتغصبك فى طاعة وصايا الله مهما كان فشلك ومهما كانت تجاربك لان خلف نفسك المهزومة يقف المسيح وفى يدية اكليل الجهاد", "الذي يعمله الرب في لحظة حضوره، لا يمكن ان تؤتيه خطط البشر، واموال الدنيا وعبقرية الخادم في ألف سنة", "كان اليهود من أشد الناس و أعنفهم فى ايمانهم بيهوه , الذى هو الله. و لما جاء المسيح جاء ليأخذ دور يهوه تماما , فكان الأمر من أصعب ما يكون على اليهود , و خاصة الكتبة و الفريسيين و رجال الكهنوت , اذ لم يطيقوا قط أن يتكلم عن نفسة كمن له سلطان يهوه و أكثر . فكونه يقول انه ابن الله , أى ابن يهوه , اعتبروا ذلك تجديفا , و أرادوا مرارا رجمه بالحجارة . فكان المسيح يلجأ فى الدفاع عن نفسه الى قوله انه يعمل اعمال الله , فلماذا الرجم , و هو قادر ان يقيم الموتى و يشفي جميع المرضى بجميع الامراض؟", "لقد دخل المسيح إلى العالم من بابه السري ( قلب الإنسان ) وإبتدأ الملكوت من داخل الإنسان لا من خارجه.", "هو سامع الصراخ، بل همس الروح وتنهد القلب. هو يرى الدموع وهي لا تزال تملأ العين قبل أن تسقط! فالذي قدم حياته ودمه فدية للخاطئ يعرف كيف يحتضن الحزين والمتألم", "نحن فينا خطية، نعم، ولكن ليست علينا خطية. لنتقدم إلى الدينونة خطاة، ولكن مبررون، محكوم علينا بالموت، ولكن تمزق الحكم وفقد صلاحية نفاذه، وألغى الموت وحصلنا على براءة في المسيح أبدية", "إني واثق أنه بمقدار اهتمامكم بالصلاة والقراءة في الإنجيل بمقدار ما تستقر حياتكم وترتاح نفوسكم، ويدوم فرحكم وسروركم", "+لا يهم المسيح أبداً من أنت .. و ماذا تكون\r\nأنت كبير أم صغير ..لك اسم أم لا ..\r\nنكرة أم علم في الكنيسة ..\r\nكل هذا لا يهمه\r\nفالجالس على أكبر كرسي في الكنيسة يفتقده الله كما يفتقد الحافي القدمين و المكسوف أن يدخل الكنيسة و يقف على رصيف الشارع ...\r\nسيان عنده هذا أو ذاك فالرب يفتش على انسان قلبه متواضع ليسكن فيه ..\r\nأو نفس مستنيرة بالروح يستطيع أن يضئ فيها", "إياك والتوقف عن الصلاة حينما لا تجاب طلباتك فتظهر كطفل متمرد، فأنت لا تعرف ما هو الصالح لك.", "الخطية لم يعد لها حق وجود أو سكنى فى طبيعتنا الجديدة، إنها أصبحت كبقعة على ثوب، ترفع فى الحال فى أقل من طرفة عين حينما يتوب الخاطىء ويطلب وجه الله.\r\nليس على الخاطىء أن يتلفت ليلتمس قوة أو واسطة غير دم المسيح ليدخل بها إلى الله ليجد الفداء والمغفرة، لئلا يهين حب الله ورحمته الفائقة ويعيب قدرته ولطفه وحنانه. ولكن له فى كل قديسى الكنيسة وتائبيها عوناً فى قدومه!!", "أخطر آية في قصة الابن الضال المثيرة «فقام وجاء إلى أبيه». هذه الحركة احتاجت من الابن أن يموت على الصليب بالجسد (البشرية) لكي “يقوم ويذهب إلى الآب” فتقوم فيه البشرية وتجيء إلى الآب. وهي أعظم حركة إيجابية في القصة كلها وعليها يدور الحديث والوصف وكل التعبيرات!", "يا سيدي.. صرنا كأموات وجئنا إليك نصلي.. ليس لنا طلبة إلا واحدة ان يفتقدنا روحك.. قلوبان ارض نارك يا ابن الله فاشعل روحك فينا", "إن الخدمة الاجتماعية حسب مفهومها العالمى لا تقوم على الشهادة للمسيح، ولا العطاء فيها يقوم على أساس شركة الأخوة فى المسيح، ولا المناداة بالتوبة، ولا على الكرازة بالملكوت، ولا على الصلاة المقتدرة، ولا على الخدام الملتهبين كاستفانوس الإلهى خادم موائد الرب، ولأن الخدمات الاجتماعية لا علاقة لها بروح الكنيسة- تقوم بها الحكومات والتى لا تؤمن بالله.\r\n«الله أنسانى كل تعبى... جعلنى مثمرا فى أرض مذلتى»\r\n(تك 41: 51)", "+حينما يهتاج غضبك و يفرغ صبرك، و قبل أن تبدأ في\r\nأن ترد أو تتخذ إجراءك، تذكر وجه المسيح و هو واقف أمام ضاربيه ثم سائرا حاملاً الصليب باهتمام و احتمال مدهش ثم على الصليب متقويا بالصبر الذى فيه والذي وهبه لك!! \r\nوهبه لك بنفس القدر و الهدوء و الشكر ليكون سندك لتكمل الشهادة حسناً.", "+الصلاة الحقيقية ليست فعلاً بشرياً ؛ هي دعوة إلهية نحن فقط نستجيب إليها ، والله دائماً مستعد لمجيئه إلينا .", "\"تتغامز الغنمات الساقطة على سقطة الراعي أما التقيات منها فيحنين ركبهن لإقامته\"", "ربما أصدقاؤنا وأهلنا والعاطفون علينا ينزعون منا فرحنا، لأننا ربما نخطىء فنتكل عليهم أكثر من نعمة الله فتفارقنا رحمة الله، أما المعاندون لنا، أما الراصدون لحركتنا المتصيدون لأخطائنا المخترعون علينا شروراً، فلا يستطيعون لأنهم صاروا لنا مصدراً إلهياً بسياق النعمة نستمد منهم تنقية ضمائرنا وكشف هزات قلوبنا وقياس أعماق حبنا أولاً بأول.", "يارب الفداء الحقيقى الذى منك نستمد كل معنى وكل قوة للفداء اعط يارب روح الفداء لرعاة شعبك، الكبير منهم والصغير، والعجوز والحدث، والمطران، والكاهن، اعطهم روح يونان يارب واما رعيتك فأعطها طاعة كطاعة نينوى لمليكها لقبول مرارة التوبة لتنجو ولا تدان مع العالم وليؤمن شعبك بالحق ان الرب قادر ان يميت ويحيى.\r\nفيا شعبا للة اطلبو الحياة بسيرة التوبة ولا تسعوا بسيرة اهل العالم فى طريق الموت.\r\nيارب اعط رعيتك جميعآ روحآ كروح نينوى فى هذا اليوم ليتوب شعبك، وتتوب كل مدن ممالك الارض إليك ولتأت ازمنة الفرج سريعآ من عندك على العالم . امين.", "+يوجد أشخاص بمجرد أن تسمع الواحد منهم أو تجلس إليه تحس مباشرة أنه ابن الإنجيل ! ابن البشارة المفرحة.", "+امسكوا بالمسيح ليمسك المسيح بكم. فتمسكنا اليوم بالمسيح ما أهونه وما أسهله، فهو أن نحبه ونحفظ وصاياه في نظير أن يمسك هو بنا ونحن أموات في خطايانا، ليعبرنا هوة الموت، ويرتفع بنا إلى أعلى السموات، لنحيا مع الله!", "+أنا أحاول أن أنقاد إلى مخافة الله، لأني أخشى أنه من كثرة تمسُّكنا بآيات التعزية، نتعوَّد تعزية أنفسنا وعدم إدانتها، وبالتالي ندين الآخرين ونُبرِّئ أنفسنا. كلُّ مَن يسقط في دينونة الآخر، يحدث في ضميره شلل، وبالتالي لا يحسُّ بخوف الله. لذلك هو يدين الآخرين بدلاً من أن يدين نفسه.", "+الكنيسة والمسيحية في هذه الأيام بدأت تضعف، ليس فقط بسبب ضعف المحبة، ولكن لأن الأساس الذي تُبنَى عليه المحبة ليس موجوداً، أَلا وهو مخافة الله", "لا يمكن أن تعرف يسوع إلا بالكنيسه لأن الكنيسه تعرفه, هو أستودع نفسه للكنيسه .\r\nعملك في الكنيسه هو التعرف علي يسوع شخصياً في اسرار الكنيسه .وليتورجياتها .", "الرهبنة هي حب، ومَن قال لك خلاف ذلك فقد ضلَّ الطريق. فهي حب بلا مقابل... ليس بأعمال جسدية شاقة نُقدِّم هذا الحب، ولا بسهر ولا بدموع ولا بصلاة ولا بأيِّ مجهود بشري كبر أو صغر، وإنما الحب الذي فينا الذي دفعنا أن نُقدِّم ذواتنا على مذبح الرب هو الذي يدفعنا لكي نُقدِّم صلاةً أو سهراً أو دموعاً أو تنهُّداً لعجزنا عن إظهار حبنا كاملاً للمسيح.", "الناس عثروا فى المسيح لاننا وضعنا المسيح فى حياتنا جنبا الى جنب على مستوى الحاجيات الاخرى على مستوى السعى لأكل خبز الجسد بل على مستوى المتعة والفسحة والتسلية والعلم والسياسة. فظهر المسيح الذى فينا أقل من قامته الحقيقية ألف ألف مرة، فان كان المسيح إلها، لزم أن يكون أعلى وأعظم وأسمى من كل شىء فى حياتنا، بل أعظم من حياتنا.", "«الراهب هو الشخص السريع التوبة، إذ يرجع باللائمة على نفسه دائماً، فهو يعلم جيداً أن النمو الروحى المنشود، مقياسه الحقيقى ليس فقط فى الخدمة والبذل والتضحية من أجل الله والناس؛ بل أيضاً احتمال الإهانة ومحقرة الذات كل يوم، ولا أنسى قط تقريراً نطقه مرةً أب مختبر إذ قال: [إن الرهبنة بدون مذلة ليس لها طعم]!.", "إذا وفق الإنسان (وهذا فى متناول يده) أن يسعد إنسانا آخر ويفرح قلبه ويفرج عن كربه وهمه، هنا شعور بسعادة أرقى وأعلى من شعور سعادة الإنسان بما ناله وحصله لنفسه. فإسعاد الآخرين هو أصلا من عمل الله ذاته، فكون الإنسان يقوم بعمل هو أصلا من أختصاص الله، فهذا يضفى على الإنسان امتدادا خارج حدود الذات، وهذه هى أصل وبداية إمكانية اتحاد الإنسان بالآخرين والله.", "المحبة شديدة و قاسية جداً ..أشد قوة من لهيب النار ..المحبة تستطيع أن تؤدبني أكثر من مخافتي لله .. عظمة الله و قوته و جبروته لم ترهبني و لم ترعبني بقدر ما أرعبتني محبته.", "\"كيف نَهْلَك و الخَلاص (المسيح) معنا في ذات القارِب !!\r\nو كيف يأتي الموت مِنْ المقدمة و الحياة رابِضة في المؤخرة !\"", "النمو في الحياة الروحية هو عمل الروح القدس الخاص و لا يحتاج لكثرة سماع أو قراءة انما يحتاج جداً لهدوء و صلاة في المخدع و تواضع و تفتيش القلب مع الصوم و القراءة في الكتاب بدموع و انسحاق لمعرفة مشيئة الله من جهة الحياة الجديدة و ليس لمعرفة قوانين أو مبادئ أو حقائق الروح و اللاهوت العالية أو الفحص عن الأمور الغامضة.", "ارفع رأسك أيها القارئ العزيز ولا تنظر اَي قصور عندك ، لا شكلا ولا موضوعا !! \r\nفطلب المسيح يتركز في دخولك ملكوته وهو مستعد ان يتغاضى عن اَي نقص او عيب فيك .\r\nفهو كفيل ان خلقة هيكلك الجسدي ليكون على اعلى لياقة ، وهو قادر ان يكمل كل نقص في سلوكك وأخلاقك !! فلا تهتم بما ينقصك", "مهما أحاطت جحافل الظلمة بالنور فلا تقربه، النور يضيء في الظلمة والظلمة لا تدركه، ومهما تشامخ الباطل وتعالى فوق الحق فبمجرَّد أن يلمسه يخر صريعاً وإذ هو لا يوجد.\r\nالرب لم يحتج ولم يوبَّخ، لم يعاتب ولم يعنف، تركهم يعملون عملهم أما هو فنظروا ولم يروه.", "الآن هو لا يدين قط، عمله الآن أن يصفح ويغفر ويطهر..\r\nلا يوبخ و لا يعاقب.. اسمع صوته ليك.. تعال، تعال الآن، أنا في انتظارك، حبي كله لك.. تعال قبل فوات الأوان، تعال قبل ان يغلق الباب !! ...", "نجد السيد المسيح يتكلم عن طيور السماء، وكيف تحيا لا همَّ لزرع أو حصاد ولا تعرف أن تجمع لنفسها قوت الغد، ثُم يسمو بسامعيه إلى إمكانية الحياة بلا همَّ، فالذي يقيت الطيور يقيتنا، والخالق لا يُضيَّع ما خلق.", "فلو سألتني ما أعظم وصية قيلت في الإنجيل تناسب حالة الإنسان الآن وفي هذا العصر، لما ترددت أن أقول :\r\n\" أمسك بالحياة الأبدية التي إليها دعاك الرب \"", "اذا كان حلول الروح القدس بالكلمة ينشيء استنارة ذهنية ووعياً للحق ثم نطقاً وشهادة للمسيح.\r\nفحلول الروح القدس بالأسرار ينشئ اتحاداً في طبيعة الله.", "نحن نخدم الآخرين لأننا أسرى محبة المسيح،\r\nوقد استعبدتنا محبته لنخدم بها وتخدم بنا.\r\nونحن رضينا بهذه العبودية الرابحة فاستعبدنا أنفسنا لخدمة الآخرين كرامة لحبه.", "ما من وسيلة ما للتعرف علي صفات الله ، إلا بالحب.", "إن اشتدت الضيقات فهذه علامة أن الشمس خلف السحاب، والوجه المنير ينتظرنا، وما بقى إلا القليل، فلنتشدد لأنه قادم للمعونة.", "فإن كنت قد ائتمنت الله ووثقت فيه أنه كفؤ أن يحفظك ويدبر حياتك، امض وراءه واتبع مشورته ولا ترجع تهتم بشيء قط، عند ذلك تنظر عمل الله معك وكيف يكون خلاصه دائمًا قريبًا من خائفيه وعنايته محيطة بهم ولو لم يبصروه !", "أما هؤلاء المتألمون في جسم الكنيسة، فالكنيسة سوف تتزين بهم ، يوم تدعي لملاقاة الرب وتتعطر بهم، لان رائحتهم تشبه رائحة الجلجثة.", "قبل ان ينتهي الميعاد، علينا أن نسلم كل ما سرقناه . صدقوني ، سرقنا الكثير لأنفسنا : حريات كاذبه، أكلتنا وأماتتنا و أضعفتنا. نسلم كل حريه كاذبه سرقناها؛ وكانت من حق الله ... أخذنا، خطفنا حريات وكرامات ليست ملكا لنا .", "فوصية المسيح تحمل قوتها سرا في داخلها ، والذي ينفذها يكتشف أن الوصية تحمل سر تنفيذها ، وتكشف معناها للجاهل ، أكثر مما تكشفه للعالم ، وللطفل الذي يتهجي الكلمات أعظم من الفيلسوف صاحب الاسم والدرجات. فوصية المسيح تؤخذ ولا تدرس ، وتقبل ولا تفحص ، فإذا أخذت وقبلت كما هي ، فهي تكشف أعماقها ، لصاحبها وتشرح أسرارها لمنفذها.", "‏المسيح محامي ذاق الظلم، ‏فيعرف ‏كيف يحامي عن المظلوم", "لا يمكن الانفكاك من الانسان العتيق الا اذا بلغ الانسان اليأس الكامل من الجمع بين الظلمة والنور، حب الذات وحب الله، تمجيد الذات و تمجيد الله، الكذب و الصلاة، النجاسه والعباده، الطمع أو الطموح والتقوى، العالم والله، الذم أو النم والمحبه، محبه الرئاسه والرهبنه او النسك", "ان البشرية ستظل تعيسة حتي تجد الله ، وهي لن تجد الله إلا في المسيح. إن عمل المسيح الخلاصي يتركز في أن نكون مثله ، نحمل أخلاقه وصفاته ، وذلك عندما يملأ حياتنا ويملك علينا.", "((سلام لكم))\r\nليست هى تحية بل عطية(سلامى اعطيكم)وليس كما يعطى اهل العالم السلام بعضهم لبعض او كما يعد الرؤساء شعوبهم بالسلام وهم فى احوج الناس اليه ! سلام المسيح هنا انشأ فيهم الفرح فى الحال والتو : (ففرح التلاميذ اذ رأوا الرب )وهكذا ابتدأ يدخلهم الفرح وسط الخوف الشديد الذى كان بعتريهم من اليهود هذه هى اول مفاعيل القيامة واشدها واكثرها دوما (ولكنى سأراكم ايضا فتفرح قلوبكم ولا ينزع احد فرحكم منكم) إنها بهجة القيامه أمضى اسلحة الايمان التى نغلب بها كل اهوال العالم ومخاوف الشيطان ومقاومة الاشرار .فالمسيحى الذى قام مع المسيح لا يعود يرهب الموت وكل تهديدات الموت لان حياته ممتدة فوق الموت واهواله لان سيرته مكتوبة فى السماويات", "قيامة المسيح هي فرح البشرية الدائم..\r\nاليوم عيد الإنسان الجديد وفرحة البشرية المقدسة لان ابن الإنسان سحق رأس الحية.. وسلم آدم وكل بنيه مفتاح الفردوس.. وفتح طريق شجرة الحياة ليأكل منها الإنسان ويعيش الي الأبد في حضن الله..", "حينما كان المسيح مع التلاميذ قبل الصليب ، كان « يُظهر لهم مجده » ، كما حدث في عُرس قانا الجليل ، لكي يتأكدوا من « لاهوته » ، وأنه « ابن الله » ، أما بعد القيامة المحسوبة أنها بحد ذاتها مجد ، وأنها برهان بُنَوّته الله ، فيكفي أن يُظهر نفسه ليتحققوا أنه هو يسوع المسيح .", "حينما كان معهم قبل أن يُصلب ، كانوا يقولون له : « يا معلّم ، كل » ، فكان يرد عليهم : « أنا لي طعام لآكل ، لستم تعرفونه أنتم »  أما بعد القيامة : « قال لهم : أعندكم ههنا طعام ؟ فناولوه جزءا من سمك مشوي وشيئاً من شهد عسل ، فأخذ ، وأكل ، قُدّامهم . »  في الأولى ، أراد أن ينبه ذهنهم أنه ليس مجرد إنسان جاء ليأكل ويشرب ، بل ليتمم رسالة إلهية ؛ وفي الثانية أراد أن ينبه ذهنهم أنه لا يزال هو الإنسان ، وأنه في ملء التجلي بالألوهة ، وأن القيامة في مجد الله لم تلغ صفاته البشرية .", "حينما كان ابن الله معهم قبل الصليب ، قيل عنه أنه « الله ظهر في الجسد » أما بعد أن مات وقام ، قيل أنه « أظهر نفسه . الحالة الأولى ، وهي التجسد ، كان وراءها معجزهٔ الإخلاء ليظهر الله في جسد إنسان ؛ والحالة الثانية هي بحد ذاتها معجزة التجلي ، ليظهر جسد الإنسان الطبيعي في مجد الألوهة ، وليثبت أن القيامة هي مجال حياة جديدة متوافقة مع طبيعة الإنسان ، ولكن متفوقة بصورة عظمى عن واقع الماديات .", "مَنْ ذا يستطيع أن يغلب في معركة الدنيا .. ويواجه صليب حنَّان أو صليب هامان، إن لم تكن حقيقة القيامة قد اتحدت بفكره وضميره، بل انفعلت في نفسه وجسده، وأعدَّته لمواجهة الموت لحساب الخلود؟", "الموت رعبٌ هو، وكل الطرق المؤدية إليه مخيفة، إلى أن تُشرق القيامة، فتُبدِّد سلطانه وتُخضعه للإنسان حتى يطأه بأقدام الإيمان كما وطئت أقدام الشعب قديماً نهر الأردن وهو في عزِّ كبريائه!", "فالفداء ألذى أكمله الله لنا بدم ابنه أصبح بمثابة لهيب قاس قاهر برودة الإنسان يرفع درجة حرارة الايمان إلى أقصى ذروتها حتى يكاد الإنسان يشتهى إن ينذبح حبا لله", "المسيح يرتاح فى الساهرين له ، وكأن نقطة التلاقى فى قمة السهر ..", "كل من أشرقت عليه قيامة المسيح فلن يرى الموت حتى لو مات و لن تحتويه ظلمة القبر حتى لو احكموا عليه مغاليق الحديد و متاريس النحاس و الاقفال ،سوف ينطلق من العالم من شمسها الضعيفه و نورها الضعيف إلى شمس البر و أنور الأبدى", "أمام الشكاكين .. \"لم تقع البشارة المفرحة عند توما موقع التصديق عن قصد من النعمة ، ليكون أباً ومرشداً الكل الذين صاروا بعقولهم قوّامين على قلوبهم ، ومدُوا أيديهم وأصابعهم عوض البصيرة ليتحسسوا بها طريق الحق . لقد صار توما في تاريخ الإيمان إمام الشكاكين . ولكن يا ليت كل من يشك ، ينطق بالنهاية بما نطق به توما. \"", "كم نشكرك يا حبيبنا يسوع من اجل قيامتك التى بها اثبت ان المحبة لا تسقط ابدا اعطنا الشجاعة كل الشجاعة ان نحب ولا يكون لمحبتنا ابدا حدود او تحفظ لتدم يا رب قيامتك وفعل قيامتك فى كنيستك وقلوب عبيدك من الان والى الابد امين", "يا ربنا يسوع المسيح يا من فرحت البشرية كلها فى تلاميذك يا من رفعت الغطاء عن قلب الحزين الباكى و اعطيتنا فرحا لا ينزع منا بقيامتك  ها انت يا ربى قد وطئت الموت بموتك وقيامتك واعطيتنا حياة ابدية من بعد موتنا . نشكرك يا الهنا لأنه من الان لا يوجد يأس لانك رفعت كل ياس وبددت كل خوف  خوف من الموت ومن كل ما يؤول الى الموت", "فنحن ”كنا في المسيح“ لما مات، ولكن لكي نقوم معه ينبغي أن ”يكون هو فينا“، يأتي، ويدخل إلينا ويصنع منزلاً وإقامة!! ولكن لا يستطيع المسيح أن يعطي قيامته كفعل حياة جديدة إلاَّ في إنسان أكمل موته تماماً عن حياته العتيقة. هذا ما كان قد سبق وعلَّم به كثيراً.", "القبر كان تعبيرا عن الفساد هذا تركه المسيح منيرا فارغا تفوح منه رائحة الاطياب و العطور و الكفن صار تذكار حياة تفوح منه رائحة القيامه و الدم المسفوك على الصليب لم يعد دم انسان مات و يمكن ان يفسد بل دم الحى المحى دم ابن الله", "هذه هى القيامة، لا يدركها أحد إلا بالاستعلان، أى حينما يكشف المسيح نفسه للقلب. لذلك لم يؤرخ الإنجيليون من القيامة إلا ومضات خاطفة ولكنها تكفى جداً أن بؤمن بها الإنسان حينما يتتبعها بالروح، ولكن يمكن أن يعيش فيها بالصلاة.", "بالصليب انتهى دهر اللاخلاص دهر الخليفة العتيقة وبالقيامة ابتداء دهر الخلاص الابدى دهر المسيح والخليقه الجديده جيل الانسان الجديد المولود من فوق لميراث ملكوت الله . صارت القيامة هى الباب الجديد الذى افتتح به الرب ازمنة الخلاص وبهجة الملكوت وانار طريق الخلود", "لقد جمع الله فى ابنه كل معاثر بنى ادم وتعدياته وصلبها فى جسده وماتت الادمية عن كل ماضيها فى الخطية والتعدى ثم اقامها المسيح معه فى اليوم الثالث خليقه اخرى جديده فيه ومنه ليس فيها ما يعوقها عن المسير فى جدة الحياة", "فالمسيح وهو فى القبر شق ظلمة الموت وخرج فى فجر الأحد بنور يملأ السماء و الأرض و ينير المسكونه الى دهر الدهور", "انظره وقد رفع يديه على الصليب ليكشف سعة حضنه يطلب المفقودين ويرفع اليأس من قلوب اليائسين", "دخل الموت ليصرعه بحياتة ونزل القبر ليقوم ويتركه فارغا --شهادة ابدية.وانحدر الى الهاوية ليصعد وفى موكب نصرته ربوات من شهود قيامته. كان لا بد ان يموت ليبطل الموت بقيامته. وكان لابد ان يظل ميتا ثلاثة ايام ليخلص الذين فى الجحيم ويصعد اعظم من منتصر\r\nكجبار حطم اسوار الجحيم وصعد وفى يديه المصاريع ومفاتيح الهاوية والموت. وفى عظمة نصرته نادى ((انا....الحى وكنت ميتا وها انا حى الى ابد الابدين))", "كل بعد عن الله يطمس معالم العقل ويضعف من عمله لإدراك ما هو الله. إذا زادت الخطية إظلم الفكر، وبالتالي يعجز عن أن يقترب من الله، لذلك يتجنب الله بإرادته ورغما عنه. وطالما تستبد به الخطية فهو يرتاح في الظلام:« وأحب الناس الظلمة أكثر من النور» أي أحبوا الخطية اكثر من النور(الله).", "لقد ترك الأكفان فى القبر تحكى إنه كان هناك", "جبار أنت يا سيدي جبار ، حقا أكملت صفة الله بجداره ، فأنت أنت الذي عرفه العهد القديم كله بصاحب الجبروت ، هذا هو جبروت الله ، إستعلنته  على الصليب بأقوى ما يكون الجبروت .", "ياربنا يسوع المسيح ننظر إلى صليبك فتسيل دموعنا ولا نعرف كيف نضبط أنفسنا..... إن هذا لسر عجيب لقد عرفنا اليوم سر صليبك يا إبن الله كيف بكل حكمه وفطنه أخفيت امجادك داخل الأمك ،حتى لا يستطيع أحد أن يختار الواحده و يترك الأخرى", "احملوا الصليب، ليس صليب الذهب ذو السلاسل الجميلة؛ ولكن صليب الموت، الموت عن العالم، الصليب ذو الآلام، وذو الصَّفْح والغفران..!\"", "يا احبائى اتوسل أليكم تحسسوا موضعكم من ضربات الظهر. تحسسوا موضعكم من بصاق الوجه. تحسسوا موضعكم من القصبة وهى تهوى على رأس المخلص إنها على رأسك يا حبيبى. \r\nاليوم يوم قضائك وان شئت وان قبلت يوم براءتك", "إن الصلاه فى جثسيمانى هى سر النصره على التهديد بالموت ،إذ كيف يخشى الموت من بلغ الموت بصلاته", "كان يهوذا من ضمن التلاميذ! وكان اللص من جماعة القتلة! لكن يا للعجب كيف استُبدلت أماكنهم.", "خذوا كلوا....اشربوا منها كلكم : إنى متعجب من ذاتى كيف اعطى لى انا الانسان الحقير الترابى الخاطئ ان اخذ المسيح فى! اخذه كله  فى داخلى؟ لست استطيع ولا احد بمستطيع ان يفسر هذا لانه فوق الفهم و التفسير ولكنى اؤمن به فهو انجيلي.....وهو نفسه قال خذوا كلوا هذا هو جسدى!! إنى لست أجترىء على شيء ليس هو لى ولكنه قال لى خذ كل. ادم اخذ من الشجرةالتى قال له الرب لا تاكل منها فاكل ومات ! وها هو المسيح يقول لى خذ كل لتحيا ... فكيف لا اكل؟؟", "وضع المسيح طقساً للرؤساء فى الكنيسة ، فالرئيس خادم للجميع ليس على مستوى الكلام بل بالإنحناء حتى غسل الأرجل", "خذوا كلوا...... اشربوا منها كلكم : ما اعظم هذا النداء ليس هو رجاء ولا دعوه ولكنه امر. ليس لنا ان نقول لا..... مهما كنا خطاة اردياء .  وليس ولا واحد مستحق هذه العطية التى يصير بها واحد مع المسيح.", "يسوع هو الباب يلزم أن ندخله ، وهو الطريق ويلزم أن نسيره ، وهو الكلمة ويلزم أن نعقله ..", "لقد اعتمد يهوذا كالتلاميذ ولم يتطهر ، وغسل المسيح رجليه، ولكنها لم تتقدس!  لذلك حُرم من نصيبه مع المسيح جملة وتفصيلاً،  بل حُرم من الحياة نفسها فالطقس لا يغير القلوب، ولكن يختم على ما فيها من كنوز.", "عجيب هذا المخلص ألذى يعلمنا كيف ندخل الموت طواعية بالصلاة النازفه", "وأقول لكم إننا علمنا، والله أعلم، أن الذي ينتقل منا تذهب روحه لتواجه المسيح لتسمع منه كلمة القبول أو الرفض بعد أن يكشف لها حياتها كلها .", "الملكوت يكتسب بالنيه في القلب أولاً ومتى إستقر القلب على ذلك ؛ إستطاع الإنسان أن يعبر الأهوال والمصاعب بقلب أسد ؛ إذ يرى  المعونة الإلهيه حاضره في كل ضيقه لأن المسيح أمين على دعوته للنهايه", "وهكذا صار العار الذي في الصلب ، أي الموت العلني مع التعرية الكاملة من كل كرامة ، مع الإضافات الجانبية إن أمكن التكميل الهُزء والتشفي من جلد وبصاق ولطم الوجه والضرب على الرأس ، هو ما يمكن أن ينتظره الإنسان الخارج على العالم ، الذي نوى أن يطلب المسيح فقط وعزم أن يتبعه!!", "أن حضور المسيح الشخصي في أسرار الكنيسة بإجرائها وممارساتها مستمر دائماً كضمان أبدي ، لفيض نعمة الحياة الجديدة على البشر إلى الأبد ..", "في الحقيقة يا أحبائي، من المستحيل أن يجوز أحد آلام المسيح إلا بالحب، وينبض نبضة الحب الإلهي", "ماتت الشجرة ومات الهيكل ، وظل هذا المثل القوي حيّا ، سيفاً مُسلّطاً على كل أمة لا تعمل البرّ ، وكل فرد يتمسك بالمظهر دون الجوهر ويفتخر بعقيدته دون أن يفتح قلبه لرب العقيدة", "كيف لا نحب صليبك يارب و نحن نقرأ أسمائنا منقوشه عليه ،و خطايانا و عارنا إنتقلت من علينا لترسم كلها على جسدك ،ثم تتساقط عليها قطرات دمك فتمحوها وآحده فواحده", "الحياة المسيحية ليست مجرد حياة انسان يؤمن بالمسيح وإنما هي المسيح حياً في الإنسان"], "news": [{"id": "fake-accounts", "title": "تحذير هام بخصوص حسابات وصفحات مزورة على الفيسبوك", "date": "2026-06-22", "kind": "warning", "images": ["fake-1.jpg", "fake-2.jpg", "fake-3.jpg"], "facts": [], "body": ["يُحذِّر دير القديس أنبا مقار ببرية شيهيت (وادي النطرون) من قيام أحد الأشخاص بانتحال صفة أحد رهبان الدير، متخذًا اسم الراهب بلامون المقاري، وإنشاء حسابات مزورة على الفيسبوك تحت مسمَّيَي “أبونا بلامون المقاري” و“أبونا بلامون الأنبا مقار”، بهدف النصب والاحتيال على المواطنين وطلب مساعدات مالية بزعم أنها لصالح الدير. كما أنه لا وجود لراهب في الدير يحمل الاسم “بلامون المقاري” (مرفق صور للحسابات المزورة).", "كما يُحذِّر الدير من صفحة مزورة أخرى تنتحل اسم المتنيح “القمص متى المسكين” تنشر محتويات غير لائقة تتضمن ألفاظًا خارجة تسيء للدير ولذكرى هذا الأب الجليل (مرفق صورة للصفحة المزورة).", "ويؤكد الدير أن لا علاقة له على الإطلاق بهذه الحسابات أو الصفحات وأنه غير مسؤول عما يصدر عنها كما أنه يحذر من التعامل معها لأنه لا يكون غرضها إلا النصب والاحتيال على الناس ونشر السجس والبلبلة"]}, {"id": "demetri", "title": "نياحة الراهب القس ديمتري المقاري", "date": "2024-04-25", "kind": "repose", "images": ["news-demetri.jpg", "news-demetri-late.jpg"], "facts": ["وُلد في 16/ 6/ 1946م", "سيمَ راهبًا في 18/10/1973م", "تنيَّح في 25/ 4/ 2024م"], "body": ["في الخميس الموافق يوم الخامس والعشرين من شهر أبريل 2024م/ 17 برمودة 1740ش، وفي عشية يوم جمعة ختام الصوم الأربعيني المقدَّس؛ زَفَّ رهبان دير القدِّيس أنبا مقار أخاهم المحبوب الراهب القس ديمتري المقاري إلى فردوس النعيم، بعد حياةٍ رهبانيَّة مجيدة امتدَّت لأكثر من نصف قرن.", "أبونا ديمتري هو من شيوخ الدير المُباركين([1])، ومن الرعيل الأول لأولاد الأب متى المسكين، والذين يرجع إليهم الفضل في وضع اللَّبنات الأُولى في إعادة إحياء وترميم هذا الدير.", "كان أبونا ديمتري راهبًا فاضلًا، عاش مُتمسِّكًا بدعوته الرهبانيَّة إلى أقصى درجة. فكان لسان حاله دائمًا أمام أيِّ موقف لا يعجبه أو لا يخصُّه: ”أنا راهب“. فكانت هذه الجملة بمثابة قرار حياته طيلة سِنِيِّ رهبنته المُباركة التي عاش أمينًا لها إلى التمام.", "كان يتميَّز بالجدِّيَّة والانضباط في حياته الشخصية، ربما إلى درجة الصرامة. فمن أجل محبته للمسيح لم يكن للعالم أو الجسد أو العاطفة سلطانٌ عليه. لذلك عاش في حرية مجد أولاد الله.", "رأيناه راهبًا مُلتزمًا ومنتظمًا في عبادته وحضوره الكنيسة يوميًّا دون انقطاع. فهو أول الرهبان الذين يُبكِّرون في حضور تسبحة نصف الليل. فكان يسبق الكل في الحضور لدرجة أنَّ أحدهم قال له مُداعبًا: ”هل أنت تبات في الكنيسة“؟! ومكانه معروفٌ في أقصى ركن بالكنيسة. وطيلة حياته كان يذهب للكنيسة قبل جرس نصف الليل بنصف ساعة على الأقل، ويوقد الشموع أمام الأيقونات، ويجلس صامتًا في مكانه في انتظار أن يدقَّ جرس نصف الليل الذي كان يعتبره يصرخ: «هُوذَا الْعَرِيسُ مُقْبِلٌ» (مت 25: 6). لقد كان بالحقيقة رجل صلاة وتسبيح وسهر روحي داخلي.", "أمَّا عن حياته الروحيَّة، التي كنا نُلاحظها، فقد كانت قراءة الإنجيل هي عمله الأول. وكان يقرأ بفهمٍ روحي عميق كُتُب الأب متى المسكين، ويحسُّ أنها تعكس له نور الإنجيل وتُعطيه قوَّة حياة. وكثيرًا ما كان ينفعل بفقرة أو فكرة معيَّنة أعجبته ولمست قلبه، فكان من فرحته يتَّصل بأحد الآباء ويُشرِكه معه في التأمل في هذه الفقرة وفي الفرح بما وجده فيها.", "قطع أبونا ديمتري علاقته تمامًا بأُسرته، وكان يرفض أن يُقابلهم أو يتواصل معهم. وعندما كانوا يأتون إلى الدير، كان يوصي أحد الآباء باستقبالهم نيابةً عنه.", "ومع التزامه الرهباني، رَفَضَ أن يقتني الأجهزة الحديثة كالكمبيوتر الذي ما كان يستعمله إلَّا في شغل مشروع الملاك ميخائيل. كما رَفَضَ أن يكون عنده تليفون أرضي داخلي، وبالطبع لم يكن عنده موبايل.", "كان أبونا ديمتري راهبًا متعدِّد المواهب، وشُعلة من النشاط والخدمة والبذل في أعمالٍ كثيرة بعيدة عن تخصُّصه. فمع إنه كان مهندسًا في الأصل؛ إلَّا أنه نجح باجتياز جميع هذه الأعمال. وقد ائتمنه الأب متى المسكين وكلَّفه بكثير من الأعمال التأسيسيَّة في الدير.", "كانت بداية خدمة الأب ديمتري في مطبخ الدير. وما أشقَّ العمل بالمطبخ في بداية السبعينيات، حيث كان العمل بعدَّة بوابير كيروسين أو شُعلة سولار. وكان يعمل وحده، ولم يكن معه حتى عامل واحد يُساعده في تأدية أعمال المطبخ المُتعدِّدة، سوى بعض المُبتدئين طالبي الرهبنة. وكان يؤدِّي كل هذه الأعمال وهو في منتهى الفرح والبذل والعطاء. وكان المطبخ مسؤولًا عن طعام الرهبان والعمال ومئات الضيوف يوميًّا. ومن الضروري أن يكون الطعام جاهزًا في تمام الساعة العاشرة والنصف صباحًا، حتى يمكن توصيله بالعربة لمساكن العمال. وبالإضافة إلى المطبخ، كان أبونا ديمتري مسؤولًا عن الدياكونية بما فيها مائدة الرهبان والفرن والمخازن.", "ثم في بداية الثمانينيات استعان به الأب متى المسكين في تأسيس المطبخ الجديد بكلِّ ما فيه من أدواتٍ حديثة تعمل بالكهرباء. وطوال سِنِيِّ عمل الأب ديمتري بالمطبخ كان يُستأمن على تشغيل الإخوة المُبتدئين طالبي الرهبنة، وكان حريصًا على تسليمهم الأصول الرهبانية من خلال العمل وحتى في تفاصيل الأكل الرهباني. وكانت الجملة التي اشتهر بها: ”إحنا ما استلمناش كده“.", "وقد تخلَّل مدَّة عمله بالمطبخ عدَّةَ شهور (من أكتوبر 1977 – مايو 1978م)، استُدعِيَ فيها للعمل في ”مدرسة سان مارك“ بالإسكندرية. وكانت بداية القصة حين زار قداسة البابا شنودة الثالث الدير في أسبوع الآلام سنة 1977م، وطلب أن يقوم الأب متى المسكين بإرسال بعض من أبنائه الرهبان للعمل في إفريقيا، والبعض الآخر لاستلام وإدارة ”مدرسة سان مارك“ بالإسكندرية. ولأجل الطاعة، وكبادرة من حُسن النيَّة، وافق الأب متى المسكين على كلِّ ما طُلِبَ منه. وكان نصيب الأب ديمتري أولًا أن يذهب للكرازة في إفريقيا. وقد قَبِل بتغصُّبٍ أن يُرسَم قسًّا لأجل هذه المهمَّة([2])؛ ولكن أُرسِلَ راهبٌ غيره إلى إفريقيا، وصار من نصيب الأب ديمتري أن يذهب مع الراهب القس يوحنا المقاري، وثلاثة رهبان آخرين لاستلام ”مدرسة سان مارك“ بالإسكندرية. وهناك استطاع أن يُكوِّن علاقاتٍ جيِّدة مع الإدارة المدرسيَّة، وتعلَّق به الشباب وأحبوه جدًّا (فهو أصلًا كان خادم شباب بكنيسة مار جرجس باسبورتنج)، وعمل لهم ”النادي العلمي“، فكانوا يتسابقون على التواجُد فيه، وكان هو من خلاله يُعطيهم نصائحه وإرشاداته. وبعد عودته للدير استعاد الأب ديمتري عمله في مطبخ الدير لعدَّة سنوات.", "وانتقل أبونا ديمتري بعد ذلك للعمل في زراعة أرض الدير بالبطيخ البعلي، هذا العمل الجديد جدًّا على الدير وقتها، والذي كان ضروريًّا في ذلك الحين للحفاظ على أرض الدير، والتي حاول الأعراب الاستيلاء عليها. فكان لا بد من زراعتها ولم يجد الأب متى المسكين أفضل من الأب ديمتري لتأسيس هذا العمل الجديد. وصار هو المُشرف على هذا المشروع الزراعي من بداية وضع البذرة الأولى حتى تسويقه خارج الدير. وهنا أيضًا ظهرت قدراته التأسيسيَّة والتنظيميَّة إلى أبعد حدٍّ.", "ثم بعد ذلك تمَّ الاستعانة بالأب ديمتري في تأسيس وتنظيم حسابات الدير. وهنا أيضًا ظهرت دقته وقدراته التأسيسيَّة إلى أبعد حدٍّ، حتى إنَّ مدير مكتب المحاسبة الذي كان يُراجع هذه الحسابات قال له: ”أنا لا أُصدِّق أنك لم تدرس المُحاسبة، فأنت أكثر دقة من كثيرين من المُحاسبين الذين يعملون معي“.", "وعندما قرَّر الأب متى المسكين سنة 2000م تأسيس مشروع الملاك ميخائيل لمعونة الأيتام والفقراء، كان أبونا ديمتري هو الراهب الذي اختاره الأب متى لإدارة هذا المشروع الضخم، وقد سلَّمه بنفسه كل تفاصيل هذه الخدمة. وهو بمساعدة أحد المهندسين في البرمجة الإلكترونيَّة، قام بوضع برنامج يحتوي على أدقِّ هذه التفاصيل عن طبيعة كل أسرة مُعالة، من حيث ظروفها وعمل الأب وسِنِّه، وعدد الأولاد ومراحلهم الدراسيَّة، وأي موارد مالية أخرى، وأيَّة مصاريف يتكبَّدونها مثل الإيجار أو أي أمراض مُزمنة يُعانون منها. ثم يُقرِّر مقدار المساعدة المُعطاة للأسرة بحيث يصل دخل العضو فيها إلى المستوى المقبول، ويُكرَّر البحث والاستقصاء مرةً أخرى كل 4 شهور، وذلك لتحديث أيِّة مستجدَّات جديدة تكون قد طرأت. هذا البرنامج، الذي وضع أساسه أبونا ديمتري، بحسب تعليمات الأب متى المسكين له، لا يزال العمل به بكلِّ دقَّة مدَّة 24 سنة بعد تأسيس هذه الخدمة.", "كان أبونا ديمتري هو رجل إدارة ونظام من الدرجة الأولى، تصل إلى درجة الصرامة، فهو في عمله يطلب الكمال، ولا يسمح بأيِّ مجال للخطإ. لذلك كان يحاول بكلِّ ما أوتي من نعمة وذكاء أن يتلافى أيَّة أخطاء يمكن أن تحدث حتى في المستقبل. وقد سلَّم الآباء العاملين معه ومن بعده، في مشروع الملاك ميخائيل، هذه الدقَّة المتناهية.", "وقد خدم الأب ديمتري مدَّة عدَّة سنوات في أرض الكيلو 70 بالساحل الشمالي، وقام خلالها بنساخة المخطوطات الأولى التي بخطِّ الأب متى المسكين، والخاصة بكلِّ كُتُب تفاسير الأناجيل، وبعض رسائل بولس الرسول، ورسالة بطرس الرسول الأولى، ورسالة يوحنا الرسول الأولى، وسِفْر أعمال الرُّسُل؛ كذلك جميع أجزاء تفسير سِفْر المزامير. وكانت نساخة الأب ديمتري لهذه المخطوطات دقيقة جدًّا وتتميَّز بالخطِّ الواضح الجميل وبالتنسيق البديع.", "عاش أبونا ديمتري الرهبنة بكلِّ كيانه، لم يتطلَّع إلى ما هو خارج الدير، ولم يسعَ نحو كرامة، فقد تحاشى الظهور أو أن يكون تحت الأضواء. مات عن العالم بالكلِّيَّة. لم يكن يتكلَّم إلَّا في حدود، ومع هذا فكانت رؤياه فقط تُلهب القلوب، وتُبكِّت البعيد، وتُرسِل رسالة خاصة لا تُخطئ لكلِّ مَنْ يلتقيه.", "[[img:news-demetri-late.jpg|الأب ديمتري قبل نياحته]]", "ومع إنَّ الأب ديمتري كان اجتماعيًّا بحسب طبيعته الخاصة، ويُجيد الكلام والمُناقشة، وله آراء سديدة في كلِّ موضوع؛ لكنه لاحَظَ في العقد الأخير من حياته الرهبانية أنَّ كثرة الكلام يمكن أن تضرَّ حياته الروحية، فأبدى صرامةً شديدة ضدَّ ميوله الطبيعية لم نَرَها في أحدٍ غيره، فصار يعيش وكأنه متوحِّدٌ وسط إخوته في المجمع. فكان لا يسمح لنفسه بكثرة الكلام، ولا حتى بالخروج من قلايته إلَّا للذهاب إلى الكنيسة. ومع ذلك فقد ظلَّ يستقبل بترحابٍ وبشاشة ومحبة شديدة أيَّ راهبٍ يزوره، وكان يُشعِر كلَّ راهب يلتقيه بأنَّ له معزَّةً ومكانةً كبيرتين في قلبه. وهو في هذا لم يكن يُبالِغ، فقد كان قلبه متَّسعًا في محبته وصلاته لأجل الجميع.", "وأخيرًا، كان لا بد أن تأتي الساعة، النهاية السعيدة، فسمح الله لحبيبه الأب ديمتري بالمرض العُضال. ولكننا نشهد أمام الله – نحن إخوته – أنه احتمل المرض بصبرٍ وشكر وتسليم كامل لإرادة الله، إلى أن انطلقت نفسه الغالية لموضع راحتها، ليسمع صوت الرب يسوع الحلو يستقبله ويقول له: «نِعِمَّا أَيُّهَا الْعَبْدُ الصَّالِحُ وَالأَمِينُ! كُنْتَ أَمِينًا فِي الْقَلِيلِ فَأُقِيمُكَ عَلَى الْكَثِيرِ. اُدْخُلْ إِلَى فَرَحِ سَيِّدِكَ» (مت 25: 21).", "[[fn:1]] كان أبونا ديمتري قد تخرَّج في كلية الهندسة جامعة الإسكندرية، وتعيَّن مُعيدًا في هندسة شبين الكوم، وأدَّى الخدمة العسكرية، وقد خرج من القوات المسلحة قبل حرب اكتوبر 1973م، وذهب مباشرةً للرهبنة في دير القدِّيس أنبا مقار. ولكن حدث أن قامت الحرب، وتمَّ استدعاء كلِّ ضباط الاحتياط المُسرَّحين، ومن ضمنهم النقيب نبيل متري (الاسم العلماني للأب ديمتري). فتمَّت رسامته راهبًا وحده، وفي غير الميعاد المُعتاد لرسامة الرهبان.", "[[fn:1+]] وفي الحقيقة، لقد ترهَّب أبونا ديمتري في ظروفٍ أُسريَّة صعبة جدًّا، فأخوه الطبيب توفي أثناء حرب أكتوبر، ووالده ووالدته كانا مُسنَّين، وكانت له أخت وحيدة صغيرة. وهنا تتكرَّر تمامًا قصة الشاب أنطونيوس الذي ترك أخته وخرج يتبع المسيح، تاركًا الرب يعتني بها.", "[[fn:2]] بعد عودته من الخدمة التي استمرت سنة دراسيَّة واحدة، اعتفى من خدمة الكهنوت نهائيًّا، حيث اعتبر أنَّ رسامته قسًّا كانت لغرضٍ معيَّن خاص، وقد انتهى هذا الغرض بنهاية خدمته."]}, {"id": "said-hakim", "title": "يودع دير القديس أنبا مقار على رجاء القيامة د. سعيد حكيم", "date": "2023-08-30", "kind": "repose", "images": ["news-said-hakim.jpg"], "facts": [], "body": ["يودع دير القديس أنبا مقار على رجاء القيامة د. سعيد حكيم، وكيل الدراسات العليا بالكلية لاكليريكية اللاهوتية القبطية الارثوذكسية وأستاذ علم الآباء بالكلية الاكليريكية اللاهوتية بالانبا رويس والعميد لاكاديمية انافورة اللاهوتية. حصل على دكتوراه في العلوم اللاهوتية من جامعة تسألونيكي باليونان وقد كان باحثا متخصصا في كتابات الآباء بمركز دراسات الاباء.", "وقد تشرف دير أنبا مقار في الشهور الأخيرة بأن ألقى فيه د. سعيد حكيم محاضرة قيمة يوم 4 نوفمبر 2022 عن “البرية والمجتمع في حياة الأنبا شنودة رئيس المتوحدين” وهو موضوع رسالته بجامعة تسالونيكي اليونانية.", "نال منها الآباء الرهبان فائدة غير قليلة واستطاعوا من خلالها أن يُقدِّروا قيمة هذا الرجل العلمية والروحية.", "وجدير بالذكر أنه عند نياحة نيافة أنبا إبيفانيوس كتب د. سعيد حكيم كلمة تقدير له بعنوان “لماذا السفر الآن؟” وننشرها الآن معتبرين أن الكثير مما قاله فيها د. سعيد ينطبق عليه هو أيضًا!", "ولكم نص كلمته عن أنبا إبيفانيوس.", "[[letter:لماذا السفر الان ؟|دكتور / سعيد حكيم]]\nيا سيدنا الحبيب نيافه الانبا ابيفانيوس : سفرك الان هو من المفاجئات غير الساره لنا نحن اللذين عرفناك .\nعرفناك هادئا وديعا رقيقا مهذبا . عرفناك بارا نقيا تقيا متفردا فى كل شئ . ولم تدعى علما ليس لك او تواضعا ليس فيك . فنحن نشهد بأن اتضاعك وصل الى ابعد حد يصل اليه الاتضاع . ومحبتك نقيه قويه للجميع ، يشهد بها كل من عرفك عن قرب ، محبه احتوت حتى المختلفين معك . قابلت الاساءه بالاحسان ، ولم ترد على اللذين هاجموك مهما كان حجم الاساءه . كنت عفيفا ، مترفعا ، متجردا فى كل شئ . همك الاول والأخير هو سلام الكنيسه ، وهدوئها ، واستقرارها ، ونموها فى الروح . اقتفاءك لاثار خطى الاباء الاوائل ، والرغبه فى نقل تعاليمهم كان محور اهتمامك . نشهد ايضا بأن روح الله قد انعم عليك باستناره خاصه ظهرت فى كلماتك وارشادك وتعليمك . نشهد بأن حضورك فى وسطنا كان يشبه تلك النسمات الرقيقه المنعشه للنفوس التواقه لهذا الحضور الملائكى .\nيا سيدنا الحبيب الخساره ليست فقط لديرك وابناءك من الرهبان ، بل للكنيسه التى فقدت عالما حقيقيا ، وراعيا امينا ، ومدبرا حكيما يندر وجوده فى هذا الزمان . عزاؤنا الان انك فى رفقه اباءك من القديسين اللذين احببتهم ومتمتع بحضور المسيح ، ونعلم ان ذاك افضل جدا . لكن سفرك الان لم يكن متوقعا ابدا ، وسيترك فراغا كبيرا ، وليس امامنا سوى ان نصلى الى الله ان يملأه بنموذج يشبهك فى محبتك وحكمتك واتضاعك ."]}], "sources": {"readings": "جدول قراءات قطمارس 2.0.1 — نص الكتاب المقدس المشكول (فاندايك)", "synaxarium": "السنكسار — حزمة أرثوذكسي", "macarius": "بستان الرهبان", "matta": "من أقوال الأب متى المسكين — تطبيق الأب متى المسكين"}};
